{
  "path": "test/test_suite.sh",
  "code": "#!/bin/bash\n\n# 检查 fuzzer.py 是否存在且可执行\nif [[ ! -x \"test/fuzzer/fuzzer.py\" ]]; then\n    echo \"[错误] fuzzer.py 不存在或不可执行\"\n    exit 1\nfi\n\n# 1. 运行Fuzzing测试\necho \"Running Fuzzing test...\"\npython3 test/fuzzer/fuzzer.py\n\n# 2. 生成测试报告\necho \"Test Report:\" > test_report.txt\necho \"1. Valid ibd file test: \" >> test_report.txt\necho \"2. Bad checksum ibd file test: \" >> test_report.txt\necho \"3. Partial page ibd file test: \" >> test_report.txt\necho \"4. SDI corrupted ibd file test: \" >> test_report.txt\necho \"5. Instant Add Column test: \" >> test_report.txt\necho \"6. BLOB Pointer corruption test: \" >> test_report.txt\necho \"7. Record corruption test: \" >> test_report.txt\necho \"8. Fuzzing test: \" >> test_report.txt\necho \"9. Memory leak check: \" >> test_report.txt\n\n# 3. 运行具体测试\nfor file in valid_ibd_file.ibd bad_checksum_ibd_file.ibd partial_page_ibd_file.ibd sdi_corrupted_ibd_file.ibd instant_add_column_ibd_file.ibd blob_pointer_corrupted_ibd_file.ibd record_corrupted_ibd_file.ibd; do\n    if [[ ! -f \"test/test_data/$file\" ]]; then\n        echo \"[警告] 文件 test/test_data/$file 不存在，跳过测试\"\n        continue\n    fi\n    echo \"Running test on $file...\"\n    ./mysql8_recovery test/test_data/$file\n    echo \"---------------------------\" >> test_report.txt\n    ./mysql8_recovery test/test_data/$file >> test_report.txt 2>&1\ndone\n\n# 4. 检查内存泄漏（仅当可执行文件存在时）\nif [[ -x \"./mysql8_recovery\" ]]; then\n    echo \"Checking for memory leaks...\" >> test_report.txt\n    valgrind --leak-check=full --show-leak-kinds=all ./mysql8_recovery test/test_data/valid_ibd_file.ibd >> test_report.txt 2>&1\nelse\n    echo \"[警告] mysql8_recovery 可执行文件不存在，跳过内存泄漏检查\" >> test_report.txt\nfi\n\n# 5. 生成摘要\necho \"Test suite completed.\" >> test_report.txt\necho \"Results saved to test_report.txt\"\n"
}